#!/usr/bin/env python3"""Weather check script for Broomfield, CO.Fetches current weather from Open-Meteo (free, no API key needed)."""import jsonimport urllib.requestfrom datetime import datetime# Broomfield, CO coordinatesLAT = 39.9205LON = -105.0867LOCATION = "Broomfield, CO"WEATHER_CODES = {    0: "☀️  Clear sky",    1: "🌤  Mainly clear",    2: "⛅  Partly cloudy",    3: "☁️  Overcast",    45: "🌫  Foggy",    48: "🌫  Depositing rime fog",    51: "🌦  Light drizzle",    53: "🌦  Moderate drizzle",    55: "🌧  Dense drizzle",    61: "🌧  Slight rain",    63: "🌧  Moderate rain",    65: "🌧  Heavy rain",    71: "🌨  Slight snow",    73: "🌨  Moderate snow",    75: "❄️  Heavy snow",    77: "❄️  Snow grains",    80: "🌦  Slight rain showers",    81: "🌧  Moderate rain showers",    82: "🌧  Violent rain showers",    85: "🌨  Slight snow showers",    86: "❄️  Heavy snow showers",    95: "⛈  Thunderstorm",    96: "⛈  Thunderstorm w/ slight hail",    99: "⛈  Thunderstorm w/ heavy hail",}def fetch_weather():    """Fetch weather data from Open-Meteo API."""    url = (        f"https://api.open-meteo.com/v1/forecast?"        f"latitude={LAT}&longitude={LON}"        f"&current=temperature_2m,relative_humidity_2m,apparent_temperature,"        f"weather_code,wind_speed_10m,wind_gusts_10m"        f"&daily=weather_code,temperature_2m_max,temperature_2m_min,"        f"precipitation_probability_max,sunrise,sunset"        f"&temperature_unit=fahrenheit"        f"&wind_speed_unit=mph"        f"&timezone=America%2FDenver"        f"&forecast_days=5"    )    req = urllib.request.Request(url, headers={"User-Agent": "weather-check/1.0"})    with urllib.request.urlopen(req, timeout=10) as resp:        return json.loads(resp.read().decode())def format_weather(data):    """Format weather data into a nice display."""    cur = data["current"]    daily = data["daily"]    temp = cur["temperature_2m"]    feels = cur["apparent_temperature"]    humidity = cur["relative_humidity_2m"]    wind = cur["wind_speed_10m"]    gusts = cur.get("wind_gusts_10m", "N/A")    code = cur["weather_code"]    condition = WEATHER_CODES.get(code, f"Unknown ({code})")    now = datetime.now()    header = f"  Weather for {LOCATION} — {now.strftime('%A, %B %d %I:%M %p')}"    lines = [        "",        "┌" + "─" * 58 + "┐",        f"│{header:<58}│",        "├" + "─" * 58 + "┤",        f"│  Currently: {condition:<44}│",        f"│  Temp: {temp:.0f}°F  (feels like {feels:.0f}°F){'':<21}│",        f"│  Humidity: {humidity}%    Wind: {wind:.0f} mph (gusts {gusts:.0f} mph){'':<6}│",        "├" + "─" * 58 + "┤",        f"│  {'5-Day Forecast':<56}│",        "├" + "─" * 58 + "┤",    ]    for i in range(len(daily["time"])):        date_str = daily["time"][i]        dt = datetime.strptime(date_str, "%Y-%m-%d")        day_label = dt.strftime("%a %b %d")        hi = daily["temperature_2m_max"][i]        lo = daily["temperature_2m_min"][i]        precip = daily["precipitation_probability_max"][i]        day_code = daily["weather_code"][i]        day_cond = WEATHER_CODES.get(day_code, "?")        line = f"  {day_label}  {day_cond:<24} {hi:.0f}°/{lo:.0f}°  💧{precip}%"        lines.append(f"│{line:<58}│")    lines.append("└" + "─" * 58 + "┘")    lines.append("")    return "\n".join(lines)def main():    try:        data = fetch_weather()        print(format_weather(data))    except Exception as e:        print(f"❌ Failed to fetch weather: {e}")        raiseif __name__ == "__main__":    main()